#include "Effects.h"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <functional>
namespace picsay {
static inline uint8_t eclamp(float v){return uint8_t(std::max(0.f,std::min(255.f,v)));}
static inline size_t ep(const Image&i,int x,int y){return (size_t(y)*i.width+x)*4;}
bool temperature(Image&a,float t){if(!a.valid())return false;t=std::max(-100.f,std::min(100.f,t));for(size_t p=0;p<a.rgba.size();p+=4){a.rgba[p]=eclamp(a.rgba[p]+t*1.35f);a.rgba[p+1]=eclamp(a.rgba[p+1]+t*.12f);a.rgba[p+2]=eclamp(a.rgba[p+2]-t*1.35f);}return true;}
bool sepia(Image&a,float amount){if(!a.valid())return false;amount=std::max(0.f,std::min(1.f,amount));for(size_t p=0;p<a.rgba.size();p+=4){float r=a.rgba[p],g=a.rgba[p+1],b=a.rgba[p+2];float sr=.393f*r+.769f*g+.189f*b,sg=.349f*r+.686f*g+.168f*b,sb=.272f*r+.534f*g+.131f*b;a.rgba[p]=eclamp(r+(sr-r)*amount);a.rgba[p+1]=eclamp(g+(sg-g)*amount);a.rgba[p+2]=eclamp(b+(sb-b)*amount);}return true;}
bool colorMatrix(Image&a,const float m[20]){if(!a.valid()||!m)return false;for(size_t p=0;p<a.rgba.size();p+=4){float v[4]={float(a.rgba[p]),float(a.rgba[p+1]),float(a.rgba[p+2]),float(a.rgba[p+3])};for(int row=0;row<4;row++)a.rgba[p+row]=eclamp(m[row*5]*v[0]+m[row*5+1]*v[1]+m[row*5+2]*v[2]+m[row*5+3]*v[3]+m[row*5+4]);}return true;}
bool sobel(Image&a,float strength){if(!a.valid())return false;Image src=a;strength=std::max(0.f,std::min(8.f,strength));const int gx[9]={-1,0,1,-2,0,2,-1,0,1},gy[9]={-1,-2,-1,0,0,0,1,2,1};for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){float sx=0,sy=0;int k=0;for(int j=-1;j<=1;j++)for(int i=-1;i<=1;i++,k++){int xx=std::max(0,std::min(a.width-1,x+i)),yy=std::max(0,std::min(a.height-1,y+j));size_t p=ep(src,xx,yy);float l=.299f*src.rgba[p]+.587f*src.rgba[p+1]+.114f*src.rgba[p+2];sx+=l*gx[k];sy+=l*gy[k];}uint8_t v=eclamp(std::sqrt(sx*sx+sy*sy)*strength/4);size_t p=ep(a,x,y);a.rgba[p]=a.rgba[p+1]=a.rgba[p+2]=v;}return true;}
bool vignette(Image&a,float strength,float radius){if(!a.valid()||radius<=0)return false;strength=std::max(0.f,std::min(1.f,strength));float cx=(a.width-1)*.5f,cy=(a.height-1)*.5f;float maxr=std::sqrt(cx*cx+cy*cy)*radius;if(maxr<=0.f)return true;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){float d=std::sqrt((x-cx)*(x-cx)+(y-cy)*(y-cy))/maxr;float f=1-strength*std::max(0.f,std::min(1.f,d*d));size_t p=ep(a,x,y);for(int c=0;c<3;c++)a.rgba[p+c]=eclamp(a.rgba[p+c]*f);}return true;}
static bool remap(Image&a,float cx,float cy,float radius,const std::function<void(float,float,float&,float&)>&fn){if(!a.valid()||radius<=0)return false;Image src=a;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){float dx=x-cx,dy=y-cy;if(dx*dx+dy*dy>radius*radius)continue;float sx=x,sy=y;fn(dx,dy,sx,sy);int ix=std::max(0,std::min(a.width-1,int(std::lround(sx)))),iy=std::max(0,std::min(a.height-1,int(std::lround(sy))));std::memcpy(&a.rgba[ep(a,x,y)],&src.rgba[ep(src,ix,iy)],4);}return true;}
bool twirl(Image&a,float cx,float cy,float radius,float radians){return remap(a,cx,cy,radius,[=](float dx,float dy,float&sx,float&sy){float d=std::sqrt(dx*dx+dy*dy),ang=radians*(1-d/radius)*(1-d/radius),c=std::cos(ang),s=std::sin(ang);sx=cx+c*dx-s*dy;sy=cy+s*dx+c*dy;});}
bool spherize(Image&a,float cx,float cy,float radius,float strength){return remap(a,cx,cy,radius,[=](float dx,float dy,float&sx,float&sy){float d=std::sqrt(dx*dx+dy*dy),f=1+strength*(1-d/radius)*(1-d/radius);sx=cx+dx*f;sy=cy+dy*f;});}
bool linearStretch(Image&a,float cx,float cy,float halfWidth,float scale){if(!a.valid()||halfWidth<=0||scale<=0)return false;Image src=a;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){float d=x-cx;if(std::abs(d)>halfWidth)continue;float f=1+(scale-1)*(1-std::abs(d)/halfWidth);int sx=std::max(0,std::min(a.width-1,int(std::lround(cx+d/f))));std::memcpy(&a.rgba[ep(a,x,y)],&src.rgba[ep(src,sx,y)],4);}return true;}
bool circleSplash(Image&a,float cx,float cy,float radius,int segments){if(!a.valid()||radius<=0||segments<3||segments>128)return false;Image src=a;const float pi=3.14159265358979323846f;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){float dx=x-cx,dy=y-cy,d=std::sqrt(dx*dx+dy*dy);if(d>=radius)continue;float ang=std::atan2(dy,dx),sector=2*pi/segments;ang=std::floor(ang/sector+.5f)*sector;float sx=cx+d*std::cos(ang),sy=cy+d*std::sin(ang);int ix=std::max(0,std::min(a.width-1,int(std::lround(sx)))),iy=std::max(0,std::min(a.height-1,int(std::lround(sy))));std::memcpy(&a.rgba[ep(a,x,y)],&src.rgba[ep(src,ix,iy)],4);}return true;}
bool mixColor(Image&a,uint32_t color,float amount){if(!a.valid())return false;amount=std::max(0.f,std::min(1.f,amount));float c[3]={float((color>>24)&255),float((color>>16)&255),float((color>>8)&255)};for(size_t p=0;p<a.rgba.size();p+=4)for(int k=0;k<3;k++)a.rgba[p+k]=eclamp(a.rgba[p+k]*(1-amount)+c[k]*amount);return true;}
bool heatMap(Image& a,float intensity){if(!a.valid())return false;intensity=std::max(0.f,std::min(1.f,intensity));for(size_t p=0;p<a.rgba.size();p+=4){float l=(.2126f*a.rgba[p]+.7152f*a.rgba[p+1]+.0722f*a.rgba[p+2])/255.f;float r=eclamp(255.f*std::min(1.f,3.f*l));float g=eclamp(255.f*std::max(0.f,std::min(1.f,3.f*l-1.f)));float b=eclamp(255.f*std::max(0.f,std::min(1.f,3.f*l-2.f)));a.rgba[p]=eclamp(a.rgba[p]*(1-intensity)+r*intensity);a.rgba[p+1]=eclamp(a.rgba[p+1]*(1-intensity)+g*intensity);a.rgba[p+2]=eclamp(a.rgba[p+2]*(1-intensity)+b*intensity);}return true;}
bool mirror(Image& a,bool horizontal,bool vertical){if(!a.valid()||(!horizontal&&!vertical))return false;Image src=a;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){int sx=horizontal?a.width-1-x:x,sy=vertical?a.height-1-y:y;std::memcpy(&a.rgba[ep(a,x,y)],&src.rgba[ep(src,sx,sy)],4);}return true;}
bool quantizeLuminance(Image& a,int levels){if(!a.valid()||levels<2||levels>256)return false;float step=255.f/(levels-1);for(size_t p=0;p<a.rgba.size();p+=4){float l=.2126f*a.rgba[p]+.7152f*a.rgba[p+1]+.0722f*a.rgba[p+2];float q=std::round(l/step)*step;float scale=l>0?q/l:0;for(int k=0;k<3;k++)a.rgba[p+k]=eclamp(a.rgba[p+k]*scale);}return true;}
bool boost(Image& a,float amount){if(!a.valid())return false;amount=std::max(-1.f,std::min(2.f,amount));for(size_t p=0;p<a.rgba.size();p+=4){float r=a.rgba[p],g=a.rgba[p+1],b=a.rgba[p+2],l=.2126f*r+.7152f*g+.0722f*b;float sat=1.f+amount*.65f,con=1.f+amount*.22f;for(int k=0;k<3;k++){float v=k==0?r:(k==1?g:b);v=l+(v-l)*sat;a.rgba[p+k]=eclamp((v-127.5f)*con+127.5f);}}return true;}
bool multiplyColor(Image& a,uint32_t color,float amount){if(!a.valid())return false;amount=std::max(0.f,std::min(1.f,amount));float m[3]={float((color>>24)&255)/255.f,float((color>>16)&255)/255.f,float((color>>8)&255)/255.f};for(size_t p=0;p<a.rgba.size();p+=4)for(int k=0;k<3;k++){float v=a.rgba[p+k]*(1-amount)+a.rgba[p+k]*m[k]*amount;a.rgba[p+k]=eclamp(v);}return true;}
}
